# Break My Fix finding 1, generated by Tracefix: set_parsing_settings returns a wrong value.
# Property (docstring): Setting stubs_resolver_allow_py_files to a bool returns None and makes the parsing setting reflect that value
# Quote: stubs_resolver_allow_py_files: Whether the stubs resolver should search
# Run it with pytest: it fails for as long as the code breaks this property.

from jsonargparse._common import set_parsing_settings, get_parsing_setting


def test_break_my_fix_1() -> None:
    validate_defaults = None
    parse_optionals_as_positionals = None
    stubs_resolver_allow_py_files = True
    # The property applies to this input: isinstance(stubs_resolver_allow_py_files, bool) and validate_defaults is None and parse_optionals_as_positionals is None
    result = set_parsing_settings(validate_defaults=validate_defaults, parse_optionals_as_positionals=parse_optionals_as_positionals, stubs_resolver_allow_py_files=stubs_resolver_allow_py_files)
    assert (result is None and get_parsing_setting('stubs_resolver_allow_py_files') == stubs_resolver_allow_py_files)
